    tilemap += tileOffset * 64 + 0x1D;
    if (ShouldDrawRematchPokeballIcon(rematchId))
    {
        tilemap[0] = POKEBALL_ICON_TOP;
        tilemap[0x20] = POKEBALL_ICON_BOTTOM;
    }
    else
    {
        tilemap[0] = POKEBALL_ICON_EMPTY;
